type DragFocusSnapshot = {
  activeTabId: string | null;
  focusedGroupId: string | null;
};

export function TerminalSplitView({
  layout,
  sessions,
  onActivateTab = () => undefined,
  onCloseTab = () => undefined,
  onCloseOtherTabs,
  onCloseTabsToRight,
  onCloseTabsToLeft,
  onReorderTab,
  onMoveTabToGroup,
  onMoveTabToSplit,
  onDetachPaneToTab,
  onRenameTab,
  onToggleTabPin,
  onAddTab = () => undefined,
  onAddBrowserTab = () => undefined,
  onAddMarkdown,
  onAddMobileEmulator,
  onOpenSettings,
  agents,
  onLaunchAgent,
  onNavigateBrowserTab = () => undefined,
  onReloadBrowserTab = () => undefined,
  onSplitPane = () => undefined,
  onClosePane = () => undefined,
  onSetRatio = () => undefined,
  onSetGroupRatio = () => undefined,
  onSwapPanes = () => undefined,
  onFocusPane = () => undefined,
  onTitleChange = () => undefined,
  onBell,
  unreadTabIds,
  activityByTabId,
  leadingSpacer = 0,
  searchLeafId,
  onCloseSearch,
}: TerminalSplitViewProps) {
  const normalizedLayout = normalizeLayout(layout);
  const groups = normalizedLayout.tabGroups ?? {};
  const groupLayout = normalizedLayout.tabGroupLayout ?? null;
  const firstGroupId = firstTabGroupId(groupLayout);
  const dragSnapshotRef = useRef<DragFocusSnapshot | null>(null);
  const activeDragRef = useRef<WorkspaceDragData | null>(null);
  const previewedTabIdRef = useRef<string | null>(null);
  const [, forceDragOverlay] = React.useReducer((value) => value + 1, 0);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 12 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  );

  const collisionDetection = useMemo<CollisionDetection>(
    () => (args) => {
      const activeData = args.active.data.current;
      if (!isWorkspaceDragData(activeData)) return pointerWithin(args);
      const dataFor = (id: UniqueIdentifier) =>
        args.droppableContainers.find((container) => container.id === id)?.data.current;
      return pointerWithin(args)
        .filter((collision) => {
          const data = dataFor(collision.id);
          return isWorkspaceDropData(data) && dropPriority(activeData, data) < 100;
        })
        .sort((left, right) => {
          const leftData = dataFor(left.id);
          const rightData = dataFor(right.id);
          if (!isWorkspaceDropData(leftData) || !isWorkspaceDropData(rightData)) return 0;
          return dropPriority(activeData, leftData) - dropPriority(activeData, rightData);
        });
    },
    [],
  );

  const splitTerminalTab = (tabId: string, direction: PaneDirection) => {
    const tab = normalizedLayout.tabs.find((candidate) => candidate.id === tabId);
    if (!tab || tab.kind === "browser") return;
    const tabLayout = getTabPaneLayout(normalizedLayout, tab);
    const targetLeafId = tabLayout.activeLeafId ?? firstLeafId(tabLayout.root);
    onSplitPane(tab.id, targetLeafId, direction);
  };

  const restoreDragFocus = () => {
    const snapshot = dragSnapshotRef.current;
    if (snapshot?.activeTabId) onActivateTab(snapshot.activeTabId);
  };

  const clearDragState = () => {
    activeDragRef.current = null;
    dragSnapshotRef.current = null;
    previewedTabIdRef.current = null;
    forceDragOverlay();
  };

  const handleDragStart = (event: DragStartEvent) => {
    const data = event.active.data.current;
    if (!isWorkspaceDragData(data)) return;
    activeDragRef.current = data;
    dragSnapshotRef.current = {
      activeTabId: normalizedLayout.activeTabId,
      focusedGroupId: normalizedLayout.focusedGroupId ?? null,
    };
    previewedTabIdRef.current = null;
    forceDragOverlay();
  };

  const handleDragOver = (event: DragOverEvent) => {
    const active = activeDragRef.current;
    const overData = event.over?.data.current;
    if (!active || active.type !== "tab" || !isWorkspaceDropData(overData)) return;

    let previewTabId: string | null = null;
    if (overData.type === "tab") previewTabId = overData.tabId;
    if (overData.type === "group-body" || overData.type === "group-edge") {
      previewTabId = groups[overData.groupId]?.activeTabId ?? groups[overData.groupId]?.tabIds[0] ?? null;
    }
    if (!previewTabId || previewTabId === active.tabId || previewedTabIdRef.current === previewTabId) return;
    previewedTabIdRef.current = previewTabId;
    onActivateTab(previewTabId);
  };

  const executeDrop = (active: WorkspaceDragData, over: WorkspaceDropData | null) => {
    const command = resolveWorkspaceDropCommand(active, over);
    if (!command) return false;

    switch (command.type) {
      case "move-tab-to-group": {
        if (onMoveTabToGroup) {
          onMoveTabToGroup(command.tabId, command.targetGroupId, command.targetIndex);
          return true;
        }
        if (active.type === "tab" && command.targetGroupId === active.groupId && command.targetIndex !== undefined) {
          onReorderTab?.(command.tabId, command.targetIndex);
          return Boolean(onReorderTab);
        }
        return false;
      }
      case "move-tab-to-split":
        onMoveTabToSplit?.(command.tabId, command.targetGroupId, command.direction, command.position);
        return Boolean(onMoveTabToSplit);
      case "detach-pane-to-tab":
        onDetachPaneToTab?.(command.sourceTabId, command.leafId, command.targetGroupId, command.targetIndex);
        return Boolean(onDetachPaneToTab);
      case "swap-panes":
        onSwapPanes(command.tabId, command.sourceLeafId, command.targetLeafId);
        return true;
    }
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const active = activeDragRef.current;
    const overData = event.over?.data.current;
    const handled = active && isWorkspaceDropData(overData) ? executeDrop(active, overData) : false;
    if (!handled) restoreDragFocus();
    clearDragState();
  };

  const handleDragCancel = (_event: DragCancelEvent) => {
    restoreDragFocus();
    clearDragState();
  };

  const sharedGroupProps: Omit<TabGroupViewProps, "groupId" | "leadingSpacer"> = {
    layout: normalizedLayout,
    groups,
    sessions,
    onActivateTab,
    onCloseTab,
    onCloseOtherTabs,
    onCloseTabsToRight,
    onCloseTabsToLeft,
    onRenameTab,
    onToggleTabPin,
    onAddTab,
    onAddBrowserTab,
    onAddMarkdown,
    onAddMobileEmulator,
    onOpenSettings,
    agents,
    onLaunchAgent,
    onNavigateBrowserTab,
    onReloadBrowserTab,
    onSplitPane,
    onMoveTabToSplit,
    onClosePane,
    onSetRatio,
    onSwapPanes,
    onFocusPane,
    onTitleChange,
    onBell,
    unreadTabIds,
    activityByTabId,
    searchLeafId,
    onCloseSearch,
    splitTerminalTab,
  };

  const activeDrag = activeDragRef.current;
  const overlayLabel =
    activeDrag?.type === "tab"
      ? normalizedLayout.tabs.find((tab) => tab.id === activeDrag.tabId)?.label ?? "Tab"
      : activeDrag?.type === "pane"
        ? "Terminal pane"
        : null;

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={collisionDetection}
      onDragStart={handleDragStart}
      onDragOver={handleDragOver}
      onDragEnd={handleDragEnd}
      onDragCancel={handleDragCancel}
    >
      <div className="relative flex flex-1 flex-col overflow-hidden bg-terminal" data-testid="terminal-layout">
        {groupLayout ? (
          <TabGroupLayoutRenderer
            node={groupLayout}
            path=""
            firstGroupId={firstGroupId}
            leadingSpacer={leadingSpacer}
            onSetGroupRatio={onSetGroupRatio}
            groupProps={sharedGroupProps}
          />
        ) : (
          <TabBar
            tabs={[]}
            activeTabId=""
            onActivate={onActivateTab}
            onClose={onCloseTab}
            onAdd={onAddTab}
            onAddBrowser={onAddBrowserTab}
            onAddMarkdown={onAddMarkdown}
            onAddMobileEmulator={onAddMobileEmulator}
            onOpenSettings={onOpenSettings}
            agents={agents}
            onLaunchAgent={onLaunchAgent}
            leadingSpacer={leadingSpacer}
          />
        )}
      </div>
      <DragOverlay dropAnimation={null}>
        {overlayLabel ? (
          <div data-testid="workspace-drag-overlay" className="rounded border border-border bg-card px-3 py-1.5 text-xs text-foreground shadow-lg">
            {overlayLabel}
          </div>
        ) : null}
      </DragOverlay>
    </DndContext>
  );
}

type TabGroupLayoutRendererProps = {
  node: TabGroupLayoutNode;
  path: string;
  firstGroupId: string | null;
  leadingSpacer: number;
  onSetGroupRatio: (path: string, ratio: number) => void;
  groupProps: Omit<TabGroupViewProps, "groupId" | "leadingSpacer">;
};

function TabGroupLayoutRenderer({ node, path, firstGroupId, leadingSpacer, onSetGroupRatio, groupProps }: TabGroupLayoutRendererProps) {
  if (node.type === "group") {
    return (
      <TabGroupView
        {...groupProps}
        groupId={node.groupId}
        leadingSpacer={node.groupId === firstGroupId ? leadingSpacer : 0}
      />
    );
  }

  const isHorizontal = node.direction === "horizontal";
  const ratio = node.ratio ?? 0.5;
  return (
    <div
      className={`relative flex h-full w-full min-h-0 min-w-0 overflow-hidden ${isHorizontal ? "flex-row" : "flex-col"}`}
      data-testid="tab-group-split"
      data-direction={node.direction}
    >
      <div className="relative min-h-0 min-w-0 overflow-hidden" style={{ flexBasis: `${ratio * 100}%`, flexGrow: 0, flexShrink: 0 }}>
        <TabGroupLayoutRenderer
          node={node.first}
          path={path ? `${path}.first` : "first"}
          firstGroupId={firstGroupId}
          leadingSpacer={leadingSpacer}
          onSetGroupRatio={onSetGroupRatio}
          groupProps={groupProps}
        />
      </div>
      <PaneResizeDivider
        direction={node.direction}
        ratio={ratio}
        ariaLabel="Resize tab groups"
        onRatioChange={(newRatio) => onSetGroupRatio(path, newRatio)}
      />
      <div className="relative min-h-0 min-w-0 flex-1 overflow-hidden" style={{ flexBasis: `${(1 - ratio) * 100}%`, flexGrow: 1, flexShrink: 1 }}>
        <TabGroupLayoutRenderer
          node={node.second}
          path={path ? `${path}.second` : "second"}
          firstGroupId={firstGroupId}
          leadingSpacer={leadingSpacer}
          onSetGroupRatio={onSetGroupRatio}
          groupProps={groupProps}
        />
      </div>
    </div>
  );
}

type TabGroupViewProps = {
  groupId: string;
  layout: LayoutState;
  groups: Record<string, TabGroup>;
  sessions: Record<string, TerminalSession>;
  leadingSpacer: number;
  onActivateTab: (tabId: string) => void;
  onCloseTab: (tabId: string) => void;
  onCloseOtherTabs?: (tabId: string) => void;
  onCloseTabsToRight?: (tabId: string) => void;
  onCloseTabsToLeft?: (tabId: string) => void;
  onRenameTab?: (tabId: string, label: string) => void;
  onToggleTabPin?: (tabId: string, pinned: boolean) => void;
  onAddTab: () => void;
  onAddBrowserTab: (url?: string) => void;
  onAddMarkdown?: () => void;
  onAddMobileEmulator?: () => void;
  onOpenSettings?: () => void;
  agents?: Array<{ name: string; command: string; args: string }>;
  onLaunchAgent?: (agent: { name: string; command: string; args: string }) => void;
  onNavigateBrowserTab: (tabId: string, url: string) => void;
  onReloadBrowserTab: (tabId: string) => void;
  onSplitPane: (tabId: string, leafId: string, direction: PaneDirection, options?: SplitPaneOptions) => void;
  onMoveTabToSplit?: (
    tabId: string,
    targetGroupId: string,
    direction: PaneDirection,
    position?: "first" | "second",
  ) => void;
  onClosePane: (tabId: string, leafId: string) => void;
  onSetRatio: (tabId: string, path: string, ratio: number) => void;
  onSwapPanes: (tabId: string, sourceLeafId: string, targetLeafId: string) => void;
  onFocusPane: (tabId: string, leafId: string) => void;
  onTitleChange: (tabId: string, title: string, sessionId?: string) => void;
  onBell?: (sessionId: string, tabId: string) => void;
  unreadTabIds?: Record<string, boolean>;
  activityByTabId?: Record<string, ActivitySummary | undefined>;
  searchLeafId?: string | null;
  onCloseSearch?: () => void;
  splitTerminalTab: (tabId: string, direction: PaneDirection) => void;
};

function TabGroupView({
  groupId,
  layout,
  groups,
  sessions,
  leadingSpacer,
  onActivateTab,
  onCloseTab,
  onCloseOtherTabs,
  onCloseTabsToRight,
  onCloseTabsToLeft,
  onRenameTab,
  onToggleTabPin,
  onAddTab,
  onAddBrowserTab,
  onAddMarkdown,
  onAddMobileEmulator,
  onOpenSettings,
  agents,
  onLaunchAgent,
  onNavigateBrowserTab,
  onReloadBrowserTab,
  onSplitPane,
  onMoveTabToSplit,
  onClosePane,
  onSetRatio,
  onSwapPanes,
  onFocusPane,
  onTitleChange,
  onBell,
  unreadTabIds,
  activityByTabId,
  searchLeafId,
  onCloseSearch,
  splitTerminalTab,
}: TabGroupViewProps) {
  const group = groups[groupId];
  if (!group) return null;
  const tabById = new Map(layout.tabs.map((tab) => [tab.id, tab]));
  const tabs = group.tabIds.map((tabId) => tabById.get(tabId)).filter((tab): tab is WorkspaceTab => Boolean(tab));
  const activeTab = tabs.find((tab) => tab.id === group.activeTabId) ?? tabs[0] ?? null;
  const activeTabLayout = activeTab ? getTabPaneLayout(layout, activeTab) : null;
  const isFocused = layout.focusedGroupId === groupId;

  const focusGroup = () => {
    if (activeTab) onActivateTab(activeTab.id);
  };

  const moveTabToSplitEdge = (tabId: string, edge: TabDropEdge) => {
    const { direction, position } = edgeToSplit(edge);
    onMoveTabToSplit?.(tabId, groupId, direction, position);
  };

  return (
    <div
      className={`relative flex h-full w-full min-h-0 min-w-0 flex-col overflow-hidden bg-terminal ${isFocused ? "" : "opacity-95"}`}
      data-testid="tab-group-panel"
      data-tab-group-panel-id={groupId}
      onPointerDown={focusGroup}
      onFocusCapture={focusGroup}
    >
      <TabBar
        groupId={groupId}
        tabs={tabs}
        activeTabId={activeTab?.id ?? ""}
        unreadTabIds={unreadTabIds}
        activityByTabId={activityByTabId}
        onActivate={onActivateTab}
        onClose={onCloseTab}
        onCloseOthers={onCloseOtherTabs}
        onCloseToRight={onCloseTabsToRight}
        onCloseToLeft={onCloseTabsToLeft}
        onRenameTab={onRenameTab}
        onTogglePin={onToggleTabPin}
        onSplitRight={(tabId) => splitTerminalTab(tabId, "horizontal")}
        onSplitDown={(tabId) => splitTerminalTab(tabId, "vertical")}
        onMoveTabToSplit={moveTabToSplitEdge}
        onAdd={() => {
          focusGroup();
          onAddTab();
        }}
        onAddBrowser={(url) => {
          focusGroup();
          onAddBrowserTab(url);
        }}
        onAddMarkdown={
          onAddMarkdown
            ? () => {
                focusGroup();
                onAddMarkdown();
              }
            : undefined
        }
        onAddMobileEmulator={
          onAddMobileEmulator
            ? () => {
                focusGroup();
                onAddMobileEmulator();
              }
            : undefined
        }
        onOpenSettings={onOpenSettings}
        agents={agents}
        onLaunchAgent={
          onLaunchAgent
            ? (agent) => {
                focusGroup();
                onLaunchAgent(agent);
              }
            : undefined
        }
        leadingSpacer={leadingSpacer}
      />

      <TabGroupDropSurface groupId={groupId}>
        {!activeTab ? null : activeTab.kind === "browser" ? (
          <BrowserPane
            tab={activeTab}
            visible={true}
            onNavigate={(url) => onNavigateBrowserTab(activeTab.id, url)}
            onReload={() => onReloadBrowserTab(activeTab.id)}
          />
        ) : activeTabLayout ? (
          <PaneRenderer
            node={activeTabLayout.root}
            tab={activeTab}
            tabLayout={activeTabLayout}
            sessions={sessions}
            groupFocused={isFocused}
            path=""
            searchLeafId={searchLeafId}
            onCloseSearch={onCloseSearch}
            onSplitPane={onSplitPane}
            onClosePane={onClosePane}
            onSetRatio={onSetRatio}
            onSwapPanes={onSwapPanes}
            onFocusPane={onFocusPane}
            onTitleChange={onTitleChange}
            onBell={onBell}
          />
        ) : null}
      </TabGroupDropSurface>
    </div>
  );
}

function getTabPaneLayout(layout: LayoutState, tab: WorkspaceTab): TabPaneLayout {
  const isBrowserTab = tab.kind === "browser";
  const fallbackLeafId = `leaf-default-${tab.id}`;
  return layout.layoutsByTabId?.[tab.id] ?? {
    root: { type: "leaf", leafId: fallbackLeafId },
    activeLeafId: fallbackLeafId,
    expandedLeafId: null,
    sessionIdsByLeafId: { [fallbackLeafId]: isBrowserTab ? "" : tab.sessionId },
  };
}

function firstLeafId(node: PaneNode): string {
  let current = node;
  while (current.type === "split") current = current.first;
  return current.leafId;
}

function firstTabGroupId(node: TabGroupLayoutNode | null): string | null {
  if (!node) return null;
  let current = node;
  while (current.type === "split") current = current.first;
  return current.groupId;
}

type PaneRendererProps = {
  node: PaneNode;
  tab: WorkspaceTab;
  tabLayout: TabPaneLayout;
  sessions: Record<string, TerminalSession>;
  groupFocused: boolean;
  path: string;
  searchLeafId?: string | null;
  onCloseSearch?: () => void;
  onSplitPane: (tabId: string, leafId: string, direction: PaneDirection, options?: SplitPaneOptions) => void;
  onClosePane: (tabId: string, leafId: string) => void;
  onSetRatio: (tabId: string, path: string, ratio: number) => void;
  onSwapPanes: (tabId: string, sourceLeafId: string, targetLeafId: string) => void;
  onFocusPane: (tabId: string, leafId: string) => void;
  onTitleChange: (tabId: string, title: string, sessionId?: string) => void;
  onBell?: (sessionId: string, tabId: string) => void;
};

function PaneRenderer(props: PaneRendererProps) {
  const { node, tab, tabLayout, sessions, path } = props;
  if (node.type === "leaf") {
    const defaultSessionId = tab.kind === "browser" ? "" : tab.sessionId;
    const sessionId = tabLayout.sessionIdsByLeafId[node.leafId] ?? defaultSessionId;
    const session = sessions[sessionId] ?? {
      id: sessionId,
      cwd: "",
      worktreePath: "",
      workspaceId: "",
      worktree: null,
      backendSessionId: null,
      lifecycle: "working" as const,
    };
    return (
      <PaneLeafView
        leafId={node.leafId}
        tab={tab}
        session={session}
        isOnlyLeaf={tabLayout.root.type === "leaf"}
        isActive={props.groupFocused && tabLayout.activeLeafId === node.leafId}
        searchOpen={props.searchLeafId === node.leafId}
        onCloseSearch={props.onCloseSearch}
        onSplitPane={props.onSplitPane}
        onClosePane={props.onClosePane}
        onFocusPane={props.onFocusPane}
        onTitleChange={props.onTitleChange}
        onBell={props.onBell}
      />
    );
  }

  const isHorizontal = node.direction === "horizontal";
  const ratio = node.ratio ?? 0.5;
  return (
    <div
      className={`relative flex h-full w-full min-h-0 min-w-0 overflow-hidden ${isHorizontal ? "flex-row" : "flex-col"}`}
      data-testid="pane-split"
      data-direction={node.direction}
    >
      <div className="relative min-h-0 min-w-0 overflow-hidden" style={{ flexBasis: `${ratio * 100}%`, flexGrow: 0, flexShrink: 0 }}>
        <PaneRenderer {...props} node={node.first} path={path ? `${path}.first` : "first"} />
      </div>
      <PaneResizeDivider
        direction={node.direction}
        ratio={ratio}
        ariaLabel="Resize terminal panes"
        onRatioChange={(newRatio) => props.onSetRatio(tab.id, path, newRatio)}
      />
      <div className="relative min-h-0 min-w-0 flex-1 overflow-hidden" style={{ flexBasis: `${(1 - ratio) * 100}%`, flexGrow: 1, flexShrink: 1 }}>
        <PaneRenderer {...props} node={node.second} path={path ? `${path}.second` : "second"} />
      </div>
    </div>
  );
}

type PaneLeafViewProps = {
  leafId: string;
  tab: WorkspaceTab;
  session: TerminalSession;
  isOnlyLeaf: boolean;
  isActive: boolean;
  searchOpen?: boolean;
  onCloseSearch?: () => void;
  onSplitPane: (tabId: string, leafId: string, direction: PaneDirection, options?: SplitPaneOptions) => void;
  onClosePane: (tabId: string, leafId: string) => void;
  onFocusPane: (tabId: string, leafId: string) => void;
  onTitleChange: (tabId: string, title: string, sessionId?: string) => void;
  onBell?: (sessionId: string, tabId: string) => void;
};

function PaneLeafView({
  leafId,
  tab,
  session,
  isOnlyLeaf,
  isActive,
  searchOpen,
  onCloseSearch,
  onSplitPane,
  onClosePane,
  onFocusPane,
  onTitleChange,
  onBell,
}: PaneLeafViewProps) {
  const [isHoveredTop, setIsHoveredTop] = React.useState(false);
  const droppable = useDroppable({
    id: `pane-leaf:${tab.id}:${leafId}`,
    data: { type: "pane-leaf", tabId: tab.id, leafId },
  });
  const draggable = useDraggable({
    id: `pane:${tab.id}:${leafId}`,
    disabled: isOnlyLeaf,
    data: { type: "pane", tabId: tab.id, leafId },
  });

  return (
    <div
      ref={droppable.setNodeRef}
      className={`relative flex h-full w-full min-h-0 min-w-0 overflow-hidden bg-terminal transition-all ${
        droppable.isOver ? "ring-2 ring-primary/80 ring-inset" : ""
      }`}
      data-testid="pane-leaf"
      data-leaf-id={leafId}
      data-tab-id={tab.id}
      data-dnd-type="pane-leaf"
      onClick={() => onFocusPane(tab.id, leafId)}
    >
      <div
        className="absolute inset-x-0 top-0 z-20 h-6"
        data-testid="pane-toolbar-hotspot"
        onMouseEnter={() => setIsHoveredTop(true)}
        onMouseLeave={(event) => {
          const related = event.relatedTarget;
          if (!(related instanceof Element) || !related.closest('[data-testid="pane-toolbar"]')) setIsHoveredTop(false);
        }}
      />

      <div
        ref={draggable.setNodeRef}
        {...draggable.attributes}
        {...draggable.listeners}
         className={`absolute inset-x-0 top-0 z-30 flex h-6 items-center justify-end border-b border-border/30 bg-background/85 backdrop-blur-md px-2 text-[11px] text-muted-foreground transition-opacity duration-150 select-none ${
          isOnlyLeaf ? "cursor-default" : "cursor-grab touch-none active:cursor-grabbing"
        } ${isHoveredTop ? "pointer-events-auto opacity-100" : "pointer-events-none opacity-0"} ${draggable.isDragging ? "opacity-30" : ""}`}
        data-testid="pane-toolbar"
        data-dnd-type="pane"
        onMouseEnter={() => setIsHoveredTop(true)}
        onMouseLeave={() => setIsHoveredTop(false)}
      >
        <div className="flex items-center gap-0.5">
          <IconButton
            label="Split pane right"
            size="sm"
            className="size-5 rounded p-0 text-muted-foreground/70 hover:bg-accent/60 hover:text-foreground"
            onPointerDown={(event) => event.stopPropagation()}
            onClick={(event) => {
              event.stopPropagation();
              onSplitPane(tab.id, leafId, "horizontal");
            }}
          >
            <Columns2 className="size-3" />
          </IconButton>
          <IconButton
            label="Split pane down"
            size="sm"
            className="size-5 rounded p-0 text-muted-foreground/70 hover:bg-accent/60 hover:text-foreground"
            onPointerDown={(event) => event.stopPropagation()}
            onClick={(event) => {
              event.stopPropagation();
              onSplitPane(tab.id, leafId, "vertical");
            }}
          >
            <Rows2 className="size-3" />
          </IconButton>
          {!isOnlyLeaf ? (
            <IconButton
              label="Close split view"
              size="sm"
              className="size-5 rounded p-0 text-muted-foreground/70 hover:bg-accent/60 hover:text-foreground"
              onPointerDown={(event) => event.stopPropagation()}
              onClick={(event) => {
                event.stopPropagation();
                onClosePane(tab.id, leafId);
              }}
            >
              <X className="size-3" />
            </IconButton>
          ) : null}
        </div>
      </div>

      <div className="h-full w-full min-h-0 flex-1 overflow-hidden">
        <TerminalPane
          session={session}
          active={isActive}
          onTitleChange={(title) => onTitleChange(tab.id, title, session.id)}
          onBell={() => onBell?.(session.id, tab.id)}
          searchOpen={searchOpen}
          onCloseSearch={onCloseSearch}
        />
      </div>
    </div>
  );
}

type PaneResizeDividerProps = {
  direction: PaneDirection;
  ratio: number;
  onRatioChange: (ratio: number) => void;
  ariaLabel?: string;
};

function PaneResizeDivider({ direction, ratio, onRatioChange, ariaLabel = "Resize terminal panes" }: PaneResizeDividerProps) {
  const dividerRef = useRef<HTMLDivElement>(null);
  const cleanupRef = useRef<(() => void) | null>(null);
  const isHorizontal = direction === "horizontal";

  useEffect(() => {
    return () => {
      if (cleanupRef.current) {
        cleanupRef.current();
        cleanupRef.current = null;
      }
    };
  }, []);

  const handlePointerDown = (event: React.PointerEvent) => {
    event.preventDefault();
    const parent = dividerRef.current?.parentElement;
    if (!parent) return;
    if (cleanupRef.current) {
      cleanupRef.current();
      cleanupRef.current = null;
    }
    document.body.style.cursor = isHorizontal ? "col-resize" : "row-resize";
    const parentRect = parent.getBoundingClientRect();

    const handlePointerMove = (pointerEvent: PointerEvent) => {
      const totalSize = isHorizontal ? parentRect.width : parentRect.height;
      if (totalSize <= 0) return;
      if (totalSize <= MIN_PANE_SIZE_PX * 2) {
        onRatioChange(0.5);
        return;
      }
      const position = isHorizontal ? pointerEvent.clientX - parentRect.left : pointerEvent.clientY - parentRect.top;
      const minimumRatio = MIN_PANE_SIZE_PX / totalSize;
      const clampedRatio = Math.max(minimumRatio, Math.min(1 - minimumRatio, position / totalSize));
      onRatioChange(Number(clampedRatio.toFixed(4)));
    };

    const cleanup = () => {
      document.body.style.cursor = "";
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", cleanup);
      window.removeEventListener("pointercancel", cleanup);
      cleanupRef.current = null;
    };

    cleanupRef.current = cleanup;
    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", cleanup);
    window.addEventListener("pointercancel", cleanup);
  };

  return (
    <div
      ref={dividerRef}
      role="separator"
      aria-label={ariaLabel}
      aria-orientation={isHorizontal ? "vertical" : "horizontal"}
      aria-valuenow={Math.round(ratio * 100)}
      data-divider-hit-target="true"
      onPointerDown={handlePointerDown}
      className={`no-drag relative z-20 shrink-0 touch-none bg-border/80 ${
        isHorizontal ? "w-px cursor-col-resize" : "h-px cursor-row-resize"
      }`}
    >
      <span
        data-divider-hit-area="true"
        className={`absolute z-10 ${
          isHorizontal ? "-inset-x-1 inset-y-0 cursor-col-resize" : "-inset-y-1 inset-x-0 cursor-row-resize"
        }`}
      />
    </div>
  );
}

import { normalizeLayout } from "../state/layout";
import { collectLeafIds, createLeafNode } from "../state/paneTree";
import type { WorkspaceState } from "../state/workspaceStore";
import {
  worktreeIdentity,
  type BrowserTab,
  type LayoutState,
  type PersistedLayout,
  type PersistedTab,
  type PersistedTerminalSession,
  type PersistedWorkspace,
  type PersistedWorkspaceSession,
  type PersistedWorktree,
  type TabGroup,
  type TerminalSession,
  type TerminalTab,
  type WorkspaceTab,
  type Worktree,
} from "./types";

export const WORKSPACE_SESSION_VERSION = 2;

export function serializeWorkspaceState(
  workspaceId: string,
  repoRoot: string,
  state: WorkspaceState,
): PersistedWorkspaceSession {
  const normalizedLayout = normalizeLayout(state.layout);
  const persistedWorktrees: PersistedWorktree[] = state.worktrees.map((wt) => ({
    path: wt.path,
    branch: wt.branch ?? "",
    head: wt.head,
    isMain: !wt.branch || wt.branch === "main" || wt.branch === "master",
    isLocked: Boolean(wt.locked),
  }));

  const persistedTabs: PersistedTab[] = normalizedLayout.tabs.map((tab) => {
    if (tab.kind === "browser") {
      return {
        id: tab.id,
        kind: "browser",
        label: tab.label,
        pinned: Boolean(tab.pinned),
        browser: {
          browserId: tab.browserId,
          url: tab.url,
          title: tab.title ?? null,
          loading: tab.loading,
          canGoBack: tab.canGoBack,
          canGoForward: tab.canGoForward,
        },
      };
    }

    const tabLayout = normalizedLayout.layoutsByTabId[tab.id];
    return {
      id: tab.id,
      kind: "terminal",
      label: tab.label,
      pinned: Boolean(tab.pinned),
      terminal: tabLayout
        ? {
            primarySessionId: tab.sessionId,
            paneTree: tabLayout.root,
            sessionIdsByLeafId: { ...tabLayout.sessionIdsByLeafId },
            activeLeafId: tabLayout.activeLeafId,
            expandedLeafId: tabLayout.expandedLeafId,
          }
        : {
            primarySessionId: tab.sessionId,
            paneTree: createLeafNode(`leaf-persisted:${tab.id}`),
            sessionIdsByLeafId: { [`leaf-persisted:${tab.id}`]: tab.sessionId },
            activeLeafId: `leaf-persisted:${tab.id}`,
            expandedLeafId: null,
          },
    };
  });

  const persistedLayout: PersistedLayout = {
    splitMode: normalizedLayout.split ?? "none",
    primaryTabId: normalizedLayout.primaryTabId ?? null,
    secondaryTabId: normalizedLayout.secondaryTabId ?? null,
    activeTabId: normalizedLayout.activeTabId ?? null,
    tabs: persistedTabs,
    tabGroups: Object.values(normalizedLayout.tabGroups ?? {}).map((group) => ({
      id: group.id,
      tabIds: [...group.tabIds],
      activeTabId: group.activeTabId,
    })),
    tabGroupLayout: normalizedLayout.tabGroupLayout ?? null,
    focusedGroupId: normalizedLayout.focusedGroupId ?? null,
  };

  const persistedTerminalSessions: Record<string, PersistedTerminalSession> = {};
  const createdAt = Date.now();
  const referencedSessionIds = new Set<string>();
  for (const tab of persistedTabs) {
    if (tab.kind === "browser") continue;
    const terminal = tab.terminal;
    if (terminal?.primarySessionId) referencedSessionIds.add(terminal.primarySessionId);
    for (const sessionId of Object.values(terminal?.sessionIdsByLeafId ?? {})) {
      if (sessionId) referencedSessionIds.add(sessionId);
    }
  }
  for (const [id, sess] of Object.entries(state.sessions)) {
    if (!sess || !referencedSessionIds.has(id)) continue;
    persistedTerminalSessions[id] = {
      localSessionId: sess.id,
      backendSessionId: sess.backendSessionId,
      worktreePath: sess.worktreePath ?? sess.cwd,
      cwd: sess.cwd,
      createdAt,
    };
  }

  const workspace: PersistedWorkspace = {
    workspaceId,
    repoRoot,
    worktrees: persistedWorktrees,
    activeWorktreePath: state.activeWorktreePath,
    layout: persistedLayout,
    terminalSessions: persistedTerminalSessions,
  };

  return {
    version: WORKSPACE_SESSION_VERSION,
    timestamp: Date.now(),
    activeWorkspaceId: workspaceId,
    workspaces: {
      [workspaceId]: workspace,
    },
  };
}

export function deserializeWorkspaceState(
  workspaceId: string,
  persistedSession: PersistedWorkspaceSession,
  liveBackendSessionIds?: Iterable<string> | null,
): WorkspaceState | null {
  const ws = persistedSession.workspaces?.[workspaceId];
  if (!ws) return null;
  const isV2 = (persistedSession.version ?? 1) >= 2;

  const liveSet = liveBackendSessionIds
    ? (liveBackendSessionIds instanceof Set ? liveBackendSessionIds : new Set(liveBackendSessionIds))
    : null;

  const worktrees: Worktree[] = (ws.worktrees || []).map((wt) => ({
    path: wt.path,
    branch: wt.branch ? (wt.branch.startsWith("refs/heads/") ? wt.branch : `refs/heads/${wt.branch}`) : null,
    head: wt.head,
    bare: false,
    detached: false,
    locked: wt.isLocked ? "locked" : null,
    prunable: null,
  }));

  const sessions: Record<string, TerminalSession> = {};
  for (const [mapKey, sess] of Object.entries(ws.terminalSessions || {})) {
    const localSessionId = sess.localSessionId || mapKey || sess.sessionId || "";
    if (!localSessionId) continue;
    const persistedBackendSessionId = isV2 ? (sess.backendSessionId ?? null) : (sess.backendSessionId ?? sess.sessionId ?? null);
    const backendSessionId = liveSet
      ? (persistedBackendSessionId && liveSet.has(persistedBackendSessionId) ? persistedBackendSessionId : null)
      : persistedBackendSessionId;
    const worktreePath = sess.worktreePath || sess.cwd;
    const matchingWorktree = worktrees.find((wt) => wt.path === worktreePath);
    sessions[localSessionId] = {
      id: localSessionId,
      cwd: sess.cwd || worktreePath,
      worktreePath,
      workspaceId,
      worktree: matchingWorktree ? worktreeIdentity(matchingWorktree) : null,
      backendSessionId,
      lifecycle: backendSessionId ? "working" : "exited",
    };
  }

  const tabs: WorkspaceTab[] = (ws.layout?.tabs || []).map((persistedTab): WorkspaceTab => {
    if (persistedTab.kind === "browser" || persistedTab.browser) {
      const browser = persistedTab.browser;
      const tab: BrowserTab = {
        id: persistedTab.id,
        kind: "browser",
        label: persistedTab.label,
        browserId: browser?.browserId ?? persistedTab.sessionId ?? `restored-browser:${persistedTab.id}`,
        url: browser?.url ?? "about:blank",
        title: browser?.title ?? persistedTab.label,
        canGoBack: browser?.canGoBack ?? false,
        canGoForward: browser?.canGoForward ?? false,
        loading: browser?.loading ?? false,
        pinned: Boolean(persistedTab.pinned),
      };
      return tab;
    }

    const primarySessionId = persistedTab.terminal?.primarySessionId ?? persistedTab.sessionId ?? "";
    const tab: TerminalTab = {
      id: persistedTab.id,
      kind: "terminal",
      sessionId: primarySessionId,
      label: persistedTab.label,
      pinned: Boolean(persistedTab.pinned),
    };
    return tab;
  });

  const layoutsByTabId: LayoutState["layoutsByTabId"] = {};
  for (const persistedTab of ws.layout?.tabs || []) {
    if (persistedTab.kind === "browser" || persistedTab.browser) {
      const leafId = `leaf-browser:${persistedTab.id}`;
      layoutsByTabId[persistedTab.id] = {
        root: createLeafNode(leafId),
        activeLeafId: leafId,
        expandedLeafId: null,
        sessionIdsByLeafId: { [leafId]: "" },
      };
      continue;
    }

    const terminal = persistedTab.terminal;
    const legacyTabLayout = ws.layout?.layoutsByTabId?.[persistedTab.id];
    const paneTree = terminal?.paneTree ?? persistedTab.paneTree ?? legacyTabLayout?.root;
    const primarySessionId = terminal?.primarySessionId ?? persistedTab.sessionId ?? "";
    const root = paneTree ?? createLeafNode(`leaf-restored:${persistedTab.id}`);
    const leafIds = collectLeafIds(root);
    const persistedMapping =
      terminal?.sessionIdsByLeafId ?? persistedTab.sessionIdsByLeafId ?? legacyTabLayout?.sessionIdsByLeafId;
    const sessionIdsByLeafId = persistedMapping && Object.keys(persistedMapping).length > 0
      ? Object.fromEntries(leafIds.map((leafId) => [leafId, persistedMapping[leafId] ?? primarySessionId]))
      : Object.fromEntries(leafIds.map((leafId) => [leafId, primarySessionId]));
    const requestedActiveLeafId =
      terminal?.activeLeafId ?? persistedTab.activeLeafId ?? legacyTabLayout?.activeLeafId ?? null;
    const requestedExpandedLeafId =
      terminal?.expandedLeafId ?? persistedTab.expandedLeafId ?? legacyTabLayout?.expandedLeafId ?? null;
    layoutsByTabId[persistedTab.id] = {
      root,
      activeLeafId: requestedActiveLeafId && leafIds.includes(requestedActiveLeafId) ? requestedActiveLeafId : leafIds[0] ?? null,
      expandedLeafId:
        requestedExpandedLeafId && leafIds.includes(requestedExpandedLeafId) ? requestedExpandedLeafId : null,
      sessionIdsByLeafId,
    };
  }

  const tabGroups: Record<string, TabGroup> | undefined = ws.layout?.tabGroups?.length
    ? Object.fromEntries(
        ws.layout.tabGroups.map((group) => [
          group.id,
          { id: group.id, tabIds: [...group.tabIds], activeTabId: group.activeTabId },
        ]),
      )
    : undefined;

  const layout = normalizeLayout({
    tabs,
    primaryTabId: ws.layout?.primaryTabId || (tabs[0]?.id ?? null),
    secondaryTabId: ws.layout?.secondaryTabId || null,
    activeTabId: ws.layout?.activeTabId || (tabs[0]?.id ?? null),
    split: (ws.layout?.splitMode as LayoutState["split"]) || "none",
    nestedSplit: null,
    layoutsByTabId,
    tabGroups,
    tabGroupLayout: ws.layout?.tabGroupLayout ?? null,
    focusedGroupId: ws.layout?.focusedGroupId ?? null,
  });

  const referencedSessionIds = new Set<string>();
  for (const tab of layout.tabs) {
    if (tab.kind === "browser") continue;
    if (tab.sessionId) referencedSessionIds.add(tab.sessionId);
    const tabLayout = layout.layoutsByTabId[tab.id];
    for (const sessionId of Object.values(tabLayout?.sessionIdsByLeafId ?? {})) {
      if (sessionId) referencedSessionIds.add(sessionId);
    }
  }
  const referencedSessions = Object.fromEntries(
    Object.entries(sessions).filter(([sessionId]) => referencedSessionIds.has(sessionId)),
  );

  return {
    worktrees,
    activeWorktreePath: ws.activeWorktreePath || (worktrees[0]?.path ?? null),
    sessions: referencedSessions,
    layout,
    unreadTabIds: {},
    unreadWorktreePaths: {},
    activityBySessionId: {},
  };
}

import type { PaneDirection, PaneNode } from "../state/paneTree";

export type WorktreeIdentity = {
  wsId: string;
  slug: string;
};

export type Worktree = {
  path: string;
  head: string;
  branch: string | null;
  bare: boolean;
  detached: boolean;
  locked: string | null;
  prunable: string | null;
};

export function worktreeIdentity(worktree: Worktree): WorktreeIdentity | null {
  const branch = worktree.branch?.replace(/^refs\/heads\//, "");
  const parts = branch?.split("/");
  if (!parts || parts.length < 3 || parts[0] !== "orca") return null;

  return { wsId: parts[1], slug: parts.slice(2).join("/") };
}

export type DirtyFile = {
  statusCode: string;
  path: string;
};

export type DirtyState = {
  isDirty: boolean;
  files: DirtyFile[];
};

export type BranchDeletionPreview = {
  branch: string;
  head: string;
  upstream: string | null;
  merged: boolean;
  ahead: number | null;
  behind: number | null;
};

export type TerminalSignal = "interrupt" | "terminate" | "kill";

export type TerminalSessionSummary = {
  sessionId: string;
  worktreePath: string | null;
};

export type TerminalLifecycle = "starting" | "working" | "waiting" | "exited" | "failed";

export type TerminalSession = {
  /** Frontend-local stable identity used by pane leaves and terminal renderer ownership. */
  id: string;
