      useWorkspaceStore({ initialWorktrees: [targetWorktree, sourceWorktree], services: workspaceServices }),
    );

    act(() => result.current.restoreWorkspace(restored));
    act(() =>
      result.current.moveTabToSplit("tab-source", "group-default", "horizontal", "first", {
        tabId: "tab-target",
        leafId: "leaf-target",
      }),
    );

    expect(result.current.state.layout.tabs.map((tab) => tab.id)).toEqual(["tab-target"]);
    expect(result.current.state.layout.layoutsByTabId["tab-source"]).toBeUndefined();
    expect(result.current.state.layout.activeTabId).toBe("tab-target");
    expect(result.current.state.layout.focusedGroupId).toBe("group-default");
    expect(result.current.state.layout.tabGroups?.["group-default"].tabIds).toEqual(["tab-target"]);

    const targetLayout = result.current.state.layout.layoutsByTabId["tab-target"];
    expect(targetLayout.root).toEqual({
      type: "split",
      direction: "horizontal",
      first: {
        type: "split",
        direction: "vertical",
        first: { type: "leaf", leafId: "leaf-source-primary" },
        second: { type: "leaf", leafId: "leaf-source-active" },
        ratio: 0.35,
      },
      second: { type: "leaf", leafId: "leaf-target" },
      ratio: 0.5,
    });
    expect(targetLayout.activeLeafId).toBe("leaf-source-active");
    expect(targetLayout.sessionIdsByLeafId).toEqual({
      "leaf-target": "session-target",
      "leaf-source-primary": "session-source-primary",
      "leaf-source-active": "session-source-active",
    });

    expect(result.current.state.sessions["session-source-primary"]).toBe(sourcePrimary);
    expect(result.current.state.sessions["session-source-active"]).toBe(sourceActive);
    expect(result.current.state.sessions["session-source-active"].cwd).toBe(sourceWorktree.path);
    expect(result.current.state.sessions["session-source-active"].backendSessionId).toBe("backend-session-source-active");
    expect(result.current.state.unreadTabIds["tab-source"]).toBeUndefined();
    expect(workspaceServices.spawnTerminal).not.toHaveBeenCalled();
    expect(workspaceServices.closeTerminal).not.toHaveBeenCalled();
  });

  it("remaps a colliding legacy leaf id while preserving the local session ownership", () => {
    const workspaceServices = services();
    const restored = stateWithSplitSource();
    restored.layout.layoutsByTabId["tab-target"] = {
      root: { type: "leaf", leafId: "leaf-shared" },
      activeLeafId: "leaf-shared",
      expandedLeafId: null,
      sessionIdsByLeafId: { "leaf-shared": "session-target" },
    };
    restored.layout.layoutsByTabId["tab-source"] = {
      root: { type: "leaf", leafId: "leaf-shared" },
      activeLeafId: "leaf-shared",
      expandedLeafId: null,
      sessionIdsByLeafId: { "leaf-shared": "session-source-primary" },
    };

    const { result } = renderHook(() =>
      useWorkspaceStore({ initialWorktrees: [targetWorktree, sourceWorktree], services: workspaceServices }),
    );
    act(() => result.current.restoreWorkspace(restored));
    act(() =>
      result.current.moveTabToSplit("tab-source", "group-default", "vertical", "second", {
        tabId: "tab-target",
        leafId: "leaf-shared",
      }),
    );

    const targetLayout = result.current.state.layout.layoutsByTabId["tab-target"];
    const leafIds = collectLeafIds(targetLayout.root);
    expect(new Set(leafIds).size).toBe(2);
    expect(leafIds).toContain("leaf-shared");
    expect(Object.values(targetLayout.sessionIdsByLeafId)).toEqual(
      expect.arrayContaining(["session-target", "session-source-primary"]),
    );
    expect(targetLayout.sessionIdsByLeafId[targetLayout.activeLeafId!]).toBe("session-source-primary");
    expect(workspaceServices.spawnTerminal).not.toHaveBeenCalled();
    expect(workspaceServices.closeTerminal).not.toHaveBeenCalled();
  });
});

import { describe, expect, it } from "vitest";

import type { TerminalTab } from "../lib/types";
import { createLayoutState, layoutReducer } from "./layout";

function tab(id: string, sessionId: string): TerminalTab {
  return { id, label: id, sessionId };
}

describe("layoutReducer with per-tab split trees", () => {
  it("initializes each tab with its own independent single-pane root layout", () => {
    const tab1 = tab("tab-1", "session-1");
    const tab2 = tab("tab-2", "session-2");
    const state = createLayoutState([tab1, tab2], tab1.id);

    expect(state.tabs).toHaveLength(2);
    expect(state.activeTabId).toBe("tab-1");
    expect(state.layoutsByTabId["tab-1"].root).toEqual({ type: "leaf", leafId: "leaf-init" });
    expect(state.layoutsByTabId["tab-1"].sessionIdsByLeafId["leaf-init"]).toBe("session-1");
    expect(state.layoutsByTabId["tab-2"].root).toEqual({ type: "leaf", leafId: "leaf-init" });
    expect(state.layoutsByTabId["tab-2"].sessionIdsByLeafId["leaf-init"]).toBe("session-2");
  });

  it("splits any pane in a tab horizontally or vertically without affecting other tabs", () => {
    const tab1 = tab("tab-1", "session-1");
    const tab2 = tab("tab-2", "session-2");
    let state = createLayoutState([tab1, tab2], tab1.id);

    state = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: "tab-1",
      targetLeafId: "leaf-init",
      direction: "horizontal",
      newLeafId: "leaf-right",
      sessionId: "session-1-right",
    });

    expect(state.layoutsByTabId["tab-1"].root).toMatchObject({
      type: "split",
      direction: "horizontal",
      first: { type: "leaf", leafId: "leaf-init" },
      second: { type: "leaf", leafId: "leaf-right" },
      ratio: 0.5,
    });
    expect(state.layoutsByTabId["tab-1"].sessionIdsByLeafId["leaf-right"]).toBe("session-1-right");
    expect(state.layoutsByTabId["tab-1"].activeLeafId).toBe("leaf-right");
    expect(state.layoutsByTabId["tab-2"].root).toEqual({ type: "leaf", leafId: "leaf-init" });

    state = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: "tab-1",
      targetLeafId: "leaf-right",
      direction: "vertical",
      newLeafId: "leaf-right-bottom",
      sessionId: "session-1-bottom",
    });

    expect(state.layoutsByTabId["tab-1"].root).toMatchObject({
      type: "split",
      direction: "horizontal",
      first: { type: "leaf", leafId: "leaf-init" },
      second: {
        type: "split",
        direction: "vertical",
        first: { type: "leaf", leafId: "leaf-right" },
        second: { type: "leaf", leafId: "leaf-right-bottom" },
      },
    });
  });

  it("rejects missing split targets and duplicate leaf ids without creating orphan session bindings", () => {
    const initial = createLayoutState([tab("tab-1", "session-1")], "tab-1");

    const missingTarget = layoutReducer(initial, {
      type: "SPLIT_PANE",
      tabId: "tab-1",
      targetLeafId: "missing",
      direction: "horizontal",
      newLeafId: "orphan",
      sessionId: "session-orphan",
    });
    expect(missingTarget).toBe(initial);
    expect(missingTarget.layoutsByTabId["tab-1"].sessionIdsByLeafId).toEqual({ "leaf-init": "session-1" });

    const duplicateLeaf = layoutReducer(initial, {
      type: "SPLIT_PANE",
      tabId: "tab-1",
      targetLeafId: "leaf-init",
      direction: "horizontal",
      newLeafId: "leaf-init",
      sessionId: "session-orphan",
    });
    expect(duplicateLeaf).toBe(initial);
  });

  it("closes an individual pane and collapses the parent split into the sibling", () => {
    const tab1 = tab("tab-1", "session-1");
    let state = createLayoutState([tab1], tab1.id);
    state = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: "tab-1",
      targetLeafId: "leaf-init",
      direction: "horizontal",
      newLeafId: "leaf-2",
      sessionId: "session-2",
    });

    state = layoutReducer(state, { type: "CLOSE_PANE", tabId: "tab-1", leafId: "leaf-2" });

    const tab1Layout = state.layoutsByTabId["tab-1"];
    expect(tab1Layout.root).toEqual({ type: "leaf", leafId: "leaf-init" });
    expect(tab1Layout.activeLeafId).toBe("leaf-init");
    expect(tab1Layout.sessionIdsByLeafId["leaf-2"]).toBeUndefined();
  });

  it("selects the adjacent tab when closing the active tab", () => {
    const tabs = [tab("tab-1", "s1"), tab("tab-2", "s2"), tab("tab-3", "s3"), tab("tab-4", "s4")];
    let state = createLayoutState(tabs, "tab-2");

    state = layoutReducer(state, { type: "CLOSE_TAB", tabId: "tab-2" });
    expect(state.activeTabId).toBe("tab-3");

    state = layoutReducer({ ...state, activeTabId: "tab-4" }, { type: "CLOSE_TAB", tabId: "tab-4" });
    expect(state.activeTabId).toBe("tab-3");
  });

  it("reorders tabs by stable tab id without disturbing active tab or pane layouts", () => {
    const state = createLayoutState([tab("tab-1", "s1"), tab("tab-2", "s2"), tab("tab-3", "s3")], "tab-2");
    const layouts = state.layoutsByTabId;

    const reordered = layoutReducer(state, { type: "REORDER_TAB", tabId: "tab-1", targetIndex: 2 });

    expect(reordered.tabs.map((item) => item.id)).toEqual(["tab-2", "tab-3", "tab-1"]);
    expect(reordered.activeTabId).toBe("tab-2");
    expect(reordered.layoutsByTabId).toBe(layouts);
  });

  it("renames and pins tabs in layout state while rejecting blank titles", () => {
    let state = createLayoutState([tab("tab-1", "s1")], "tab-1");
    state = layoutReducer(state, { type: "RENAME_TAB", tabId: "tab-1", label: "  custom title  " });
    state = layoutReducer(state, { type: "SET_TAB_PINNED", tabId: "tab-1", pinned: true });

    expect(state.tabs[0]).toMatchObject({ label: "custom title", pinned: true });
    const unchanged = layoutReducer(state, { type: "RENAME_TAB", tabId: "tab-1", label: "   " });
    expect(unchanged).toBe(state);
  });

  it("ignores focus requests for leaves that do not exist", () => {
    const state = createLayoutState([tab("tab-1", "session-1")], "tab-1");
    const focused = layoutReducer(state, { type: "FOCUS_PANE", tabId: "tab-1", leafId: "missing" });
    expect(focused).toBe(state);
    expect(focused.layoutsByTabId["tab-1"].activeLeafId).toBe("leaf-init");
  });

  it("normalizes stale pane session mappings to the actual leaf set", () => {
    const state = createLayoutState([tab("tab-1", "session-1")], "tab-1");
    const malformed = {
      ...state,
      layoutsByTabId: {
        ...state.layoutsByTabId,
        "tab-1": {
          ...state.layoutsByTabId["tab-1"],
          sessionIdsByLeafId: { "leaf-init": "session-1", ghost: "session-ghost" },
        },
      },
    };

    const normalized = layoutReducer(malformed, { type: "ACTIVATE_TAB", tabId: "tab-1" });
    expect(normalized.layoutsByTabId["tab-1"].sessionIdsByLeafId).toEqual({ "leaf-init": "session-1" });
  });

  it("swaps pane positions for drag-and-drop reorder", () => {
    let state = createLayoutState([tab("tab-1", "session-1")], "tab-1");
    state = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: "tab-1",
      targetLeafId: "leaf-init",
      direction: "horizontal",
      newLeafId: "leaf-2",
      sessionId: "session-2",
    });

    state = layoutReducer(state, {
      type: "SWAP_PANES",
      tabId: "tab-1",
      sourceLeafId: "leaf-init",
      targetLeafId: "leaf-2",
    });

    expect(state.layoutsByTabId["tab-1"].root).toMatchObject({
      type: "split",
      first: { type: "leaf", leafId: "leaf-2" },
      second: { type: "leaf", leafId: "leaf-init" },
    });
  });

  it("adjusts split ratio at dot path", () => {
    let state = createLayoutState([tab("tab-1", "session-1")], "tab-1");
    state = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: "tab-1",
      targetLeafId: "leaf-init",
      direction: "horizontal",
      newLeafId: "leaf-2",
      sessionId: "session-2",
    });

    state = layoutReducer(state, { type: "SET_PANE_RATIO", tabId: "tab-1", path: "", ratio: 0.7 });
    expect(state.layoutsByTabId["tab-1"].root).toMatchObject({ type: "split", ratio: 0.7 });
  });
});

import { describe, expect, it } from "vitest";

import type { LayoutState, TerminalTab } from "../lib/types";
import { getGroupForTab, layoutReducer, normalizeLayout } from "./layout";
import { moveTabIntoPaneSplit } from "./tabPaneDrop";

function sameTabLayout(): LayoutState {
  const tab: TerminalTab = { id: "tab-main", label: "main", sessionId: "session-a" };
  return normalizeLayout({
    tabs: [tab],
    activeTabId: tab.id,
    layoutsByTabId: {
      [tab.id]: {
        root: {
          type: "split",
          direction: "horizontal",
          first: { type: "leaf", leafId: "leaf-a" },
          second: {
            type: "split",
            direction: "vertical",
            first: { type: "leaf", leafId: "leaf-b" },
            second: { type: "leaf", leafId: "leaf-c" },
            ratio: 0.5,
          },
          ratio: 0.4,
        },
        activeLeafId: "leaf-a",
        expandedLeafId: null,
        sessionIdsByLeafId: {
          "leaf-a": "session-a",
          "leaf-b": "session-b",
          "leaf-c": "session-c",
        },
      },
    },
  });
}

describe("pane-handle edge drop composition", () => {
  it("detaches the existing pane session and reinserts that exact leaf at the target edge", () => {
    const state = sameTabLayout();
    const groupId = getGroupForTab(state, "tab-main")!.id;
    const detachedTab: TerminalTab = { id: "tab-detached", label: "main", sessionId: "session-a" };

    const detached = layoutReducer(state, {
      type: "DETACH_PANE_TO_TAB",
      sourceTabId: "tab-main",
      leafId: "leaf-a",
      newTab: detachedTab,
      targetGroupId: groupId,
    });
    const next = moveTabIntoPaneSplit(
      detached,
      detachedTab.id,
      "tab-main",
      "leaf-c",
      "vertical",
      "first",
    );

    expect(next.tabs.map((tab) => tab.id)).toEqual(["tab-main"]);
    expect(next.layoutsByTabId["tab-main"].root).toEqual({
      type: "split",
      direction: "vertical",
      first: { type: "leaf", leafId: "leaf-b" },
      second: {
        type: "split",
        direction: "vertical",
        first: { type: "leaf", leafId: "leaf-a" },
        second: { type: "leaf", leafId: "leaf-c" },
        ratio: 0.5,
      },
      ratio: 0.5,
    });
    expect(next.layoutsByTabId["tab-main"].activeLeafId).toBe("leaf-a");
    expect(next.layoutsByTabId["tab-main"].sessionIdsByLeafId).toEqual({
      "leaf-a": "session-a",
      "leaf-b": "session-b",
      "leaf-c": "session-c",
    });
  });

  it("preserves pane ownership when a handle is moved to an edge in another tab", () => {
    const source: TerminalTab = { id: "tab-source", label: "source", sessionId: "session-moved" };
    const target: TerminalTab = { id: "tab-target", label: "target", sessionId: "session-target" };
    const state = normalizeLayout({
      tabs: [source, target],
      activeTabId: source.id,
      layoutsByTabId: {
        [source.id]: {
          root: {
            type: "split",
            direction: "horizontal",
            first: { type: "leaf", leafId: "leaf-moved" },
            second: { type: "leaf", leafId: "leaf-remain" },
            ratio: 0.5,
          },
          activeLeafId: "leaf-moved",
          expandedLeafId: null,
          sessionIdsByLeafId: {
            "leaf-moved": "session-moved",
            "leaf-remain": "session-remain",
          },
        },
        [target.id]: {
          root: { type: "leaf", leafId: "leaf-target" },
          activeLeafId: "leaf-target",
          expandedLeafId: null,
          sessionIdsByLeafId: { "leaf-target": "session-target" },
        },
      },
    });
    const targetGroupId = getGroupForTab(state, target.id)!.id;
    const detachedTab: TerminalTab = { id: "tab-detached", label: "source", sessionId: "session-moved" };

    const detached = layoutReducer(state, {
      type: "DETACH_PANE_TO_TAB",
      sourceTabId: source.id,
      leafId: "leaf-moved",
      newTab: detachedTab,
      targetGroupId,
    });
    const next = moveTabIntoPaneSplit(
      detached,
      detachedTab.id,
      target.id,
      "leaf-target",
      "horizontal",
      "second",
    );

    expect(next.tabs.find((tab) => tab.id === source.id)).toMatchObject({ sessionId: "session-remain" });
    expect(next.layoutsByTabId[source.id]).toMatchObject({
      root: { type: "leaf", leafId: "leaf-remain" },
      activeLeafId: "leaf-remain",
      sessionIdsByLeafId: { "leaf-remain": "session-remain" },
    });
    expect(next.layoutsByTabId[target.id].root).toEqual({
      type: "split",
      direction: "horizontal",
      first: { type: "leaf", leafId: "leaf-target" },
      second: { type: "leaf", leafId: "leaf-moved" },
      ratio: 0.5,
    });
    expect(next.layoutsByTabId[target.id].sessionIdsByLeafId).toEqual({
      "leaf-target": "session-target",
      "leaf-moved": "session-moved",
    });
    expect(next.layoutsByTabId[target.id].activeLeafId).toBe("leaf-moved");
  });
});

