  it("dispatches terminal-pane split actions from pane toolbar buttons", () => {
    const onSplitPane = vi.fn();
    render(
      <TerminalSplitView
        layout={singleTabLayout()}
        sessions={{ "session-1": session("session-1", "backend-1") }}
